/** @dynamicRequire */
export async function stopHandler(args: readonly string[]): Promise<void> {
  if (args.includes('--help') || args.includes('-h')) {
    process.stdout.write(`Usage: ccb stop <short> [--force | --detach]\n\n  Stop a running background session. SIGTERM by default; --force / -9 → SIGKILL;\n  --detach: leave worker running, daemon stops supervising (re-attach with ccb attach).\n`); return
  }
  const positional = args.filter(a => !a.startsWith('-'))
  const short = positional[0]
  const force = args.includes('--force') || args.includes('-9')
  const detach = args.includes('--detach')
  if (!short) { process.stderr.write('Usage: ccb stop <short> [--force | --detach]\n'); process.exit(1) }
  const job = resolveJobOrExit(short)
  if (detach) {
    const { isDaemonAlive, daemonDetach } = await import('./bg/daemonAdapter.js')
    if (await isDaemonAlive()) {
      const r = await daemonDetach(job.short)
      if (r.ok) {
        ;(await import('./bg/agentActionEvent.js')).emitAgentAction('stop', job.short, { detach: 'true' })
        process.stdout.write(`Detached ${job.short} (worker still running)\n`); return
      }
      process.stderr.write(`detach failed (${r.code}); falling back to graceful stop\n`)
    } else process.stderr.write(`detach requires daemon; falling back to graceful stop\n`)
  }
  ;(await import('./bg/agentActionEvent.js')).emitAgentAction(force ? 'kill' : 'stop', job.short)
  await stopJob(job, { force, verbLabel: force ? 'Killed' : 'Stopped', finalStatus: force ? 'killed' : 'stopped' })
}

/** Alias for `stop --force`. @dynamicRequire */
export async function killHandler(args: readonly string[]): Promise<void> {
  if (args.includes('--help') || args.includes('-h')) {
    process.stdout.write(`Usage: ccb kill <short>\n\n  Alias for \`ccb stop --force\` — sends SIGKILL immediately.\n`); return
  }
  const short = args.filter(a => !a.startsWith('-'))[0]
  if (!short) { process.stderr.write('Usage: ccb kill <short>   (alias of `ccb stop --force`)\n'); process.exit(1) }
  const job = resolveJobOrExit(short)
  ;(await import('./bg/agentActionEvent.js')).emitAgentAction('kill', job.short)
  await stopJob(job, { force: true, verbLabel: 'Killed', finalStatus: 'killed' })
}

/** @dynamicRequire */
export async function rmHandler(args: readonly string[]): Promise<void> {
  if (args.includes('--help') || args.includes('-h')) {
    process.stdout.write(
      `Usage: ccb rm <short>\n\n  Remove a stopped background session's job directory (meta.json + log files).\n  Refuses to act on a still-running job — \`ccb stop\` it first.\n`,
    )
    return
  }
  const short = args[0]
  if (!short) {
    process.stderr.write('Usage: ccb rm <short>\n')
    process.exit(1)
  }
  const job = resolveJobOrExit(short)
  if (job.status === 'running') {
    process.stderr.write(
      `Job ${job.short} is still running. Run "ccb kill ${job.short}" first.\n`,
    )
    process.exit(1)
  }
  ;(await import('./bg/agentActionEvent.js')).emitAgentAction('rm', job.short)
  rmSync(getJobDir(job.short), { recursive: true, force: true })
  process.stdout.write(`Removed ${job.short}.\n`)
}

/** @dynamicRequire */
export async function attachHandler(args: readonly string[]): Promise<void> {
  if (args.includes('--help') || args.includes('-h')) {
    process.stdout.write(
      `Usage: ccb attach <short>\n  pty-mode: bidirectional (Ctrl+Q detach). detached-mode: logs --follow.\n`,
    )
    return
  }
  const positional = args.filter(a => !a.startsWith('-'))
  if (!positional[0]) {
    process.stderr.write('Usage: ccb attach <short>\n')
    process.exit(1)
  }
  const job = resolveJobOrExit(positional[0]!)
  ;(await import('./bg/agentActionEvent.js')).emitAgentAction('attach', job.short, { mode: job.mode ?? 'detached' })
  if (job.mode === 'pty' && job.ptySocket) {
    const { runAttach } = await import('./bg/attachClient.js')
    await runAttach(job.ptySocket, job.short)
    return
  }
  // detached-mode is non-PTY: log + fall through to logs --follow.
  ;(await import('./bg/agentActionEvent.js')).emitAgentActionRaw('tengu_bg_attach_legacy_autorespawn', { short: job.short, mode: job.mode ?? 'detached' })
  process.stderr.write(`attach: detached-mode job — streaming read-only. Use --bg-pty for bidirectional.\n`)
  await logsHandler([job.short, '--follow', '--tail', '200'])
}

/**
 * `ccb respawn <short>|--all` — restart a bg job (or all live ones)
 * using the same directive + flags. Mirrors ant 4649.js sM3, daemon-
 * less: stop+rm the old job and spawn fresh. New short id is issued
 * (ant preserves the id via daemon — not feasible without one). Exit
 * 0 if all respawns succeeded, 1 if any failed.
 *
 * @dynamicRequire
 */
export async function respawnHandler(args: readonly string[]): Promise<void> {
  const positional = args.filter(a => !a.startsWith('-'))
  const arg = args[0]
  if (arg === '--help' || arg === '-h') {
    process.stdout.write(
      `Usage: ccb respawn <short>|--all\n\n  Restart a background session (or all live ones) using the original directive + flags.\n  Issued a new short id; the old job dir is removed.\n`,
    )
    return
  }

  // RespawnJobMeta es una vista reducida de JobMeta (declarada aparte en
  // respawnJob.ts para evitar un ciclo de imports); el valor real que
  // respawnSingle escribe siempre trae los campos completos de JobMeta.
  const helpers = {
    getJobDir,
    generateShortId,
    spawnBgJob,
    writeJobMeta: (meta: RespawnJobMeta) => writeJobMeta(meta as JobMeta),
  }

  if (args.includes('--all')) {
    const { respawnSingle } = await import('./bg/respawnJob.js')
    const targets = listJobs().filter(j => j.status === 'running')
    if (targets.length === 0) {
      process.stdout.write('no live jobs to respawn\n')
      return
    }
    let okCount = 0
    for (const j of targets) {
      const restarted = await respawnSingle(j, helpers)
      if (restarted) okCount++
    }
    if (okCount < targets.length) process.exit(1)
    return
  }

  const short = positional[0]
  if (!short) {
    process.stderr.write('Usage: ccb respawn <short>|--all\n')
    process.exit(1)
  }
  const job = resolveJobOrExit(short)
  ;(await import('./bg/agentActionEvent.js')).emitAgentAction('respawn', job.short)
  const { respawnSingle } = await import('./bg/respawnJob.js')
  const ok = await respawnSingle(job, helpers)
  if (!ok) process.exit(1)
}

export { extractRespawnArgs, splitBgArgs, tailFile }
export { runPtyHost } from './bg/ptyHost.js'

import { spawn, type ChildProcess } from 'child_process'
import { resolve } from 'path'
import { errorMessage } from '@thyrox/local-observability/errorHelpers.js'
import { logError } from '@thyrox/local-observability/logging'
import { logEvent } from '@thyrox/local-observability'
import { PRODUCT_NAME } from '@thyrox/config/product'
import { getConfigHomeDir } from '@thyrox/config/env/configHome.js'

/**
 * Código de salida de un worker con fallo permanente (no reintentable).
 * `jq` en `chunk-92tvramn.js` (`class Ue`, referencia 2.1.283): mismo valor.
 * @see workerRegistry.ts EXIT_CODE_PERMANENT
 */
const EXIT_CODE_PERMANENT = 78

/**
 * Backoff exponencial con jitter para reintentar un worker caído. Porte de
 * `Ar`/`At` (`chunk-92tvramn.js`, `class Ue`, referencia 2.1.283):
 * `Ar(r) = At(min(1000*2**r, Er))`, `At(r) = round(r*(0.5+random()))`.
 *
 * Divergencia declarada: lo que antes existía aquí —parking permanente tras
 * `MAX_RAPID_FAILURES` fallos rápidos— no tiene equivalente en `Ue.onExit`:
 * la referencia reintenta indefinidamente con este backoff (topado en
 * `Er`=300000ms) y sólo aparca de forma permanente por `EXIT_CODE_PERMANENT`
 * (`jq`). Se retira esa lógica para igualar la referencia.
 */
const WORKER_BACKOFF_BASE_MS = 1_000 // el `1000` de `Ar`
const WORKER_BACKOFF_CAP_MS = 300_000 // `Er`

/**
 * Uptime mínimo para tratar una salida con código 0 como sana y resetear la
 * racha de fallos. `br` (60000) en `Ue.onExit`, misma referencia.
 *
 * // pendiente: `Ue.onExit` también trata como fallo permanente (sin
 * // reintentar) una salida limpia y rápida cuando el worker corre a través
 * // de un "launcher" (`r===0 && n<zNe && lu().length>0`, `zNe`=12000ms) y
 * // el reintento de spawn por error `ENOENT`/`EACCES` con código `Tpt`=75.
 * // Ninguna de las dos aplica aquí: este supervisor lanza el worker
 * // directamente con `spawn(process.execPath, …)`, sin el concepto de
 * // "process wrapper"/launcher que esas dos ramas asumen.
 */
const WORKER_HEALTHY_UPTIME_MS = 60_000

interface WorkerState {
  kind: string
  process: ChildProcess | null
  consecutiveCrashes: number
  parked: boolean
  lastStartTime: number
}

/**
 * Daemon supervisor entry point. Called from `cli.tsx` via:
 *   `claude daemon [subcommand]`
 *
 * Starts and supervises long-running workers. Currently spawns one
 * `remoteControl` worker that runs the headless bridge server.
 *
 * Subcommands:
 *   (none)  — start the supervisor with default workers
 *   start   — same as no subcommand
 *   status  — print worker status (TODO: IPC)
 *   stop    — send SIGTERM to supervisor (TODO: PID file)
 */
export async function daemonMain(args: string[]): Promise<void> {
  const subcommand = args[0] || 'start'

  switch (subcommand) {
    case 'start':
      try {
        await runSupervisor(args.slice(1))
      } catch (e) {
        // ant 5170 — startup_crash: supervisor failed to bring itself
        // online. Report so admins notice; rethrow to preserve exit
        // code semantics.
        reportDaemonStartupCrash(e)
        throw e
      }
      break
    case 'bg': {
      // ccb daemon bg [run|status|stop|install|uninstall|start|restart] — bg supervisor.
      const sub = args[1] || 'run'
      if (sub === 'run') {
        const { bgDaemonMain } = await import('./bgDaemon.js')
        let code = 1
        try {
          code = await bgDaemonMain(args.slice(2))
        } catch (e) {
          reportDaemonStartupCrash(e, { sub: 'bg' })
          throw e
        }
        process.exitCode = code
      } else if (sub === 'status' || sub === 'list') {
        await bgDaemonStatus(args.includes('--json'))
      } else if (sub === 'log') {
        await bgDaemonTailLog()
      } else if (sub === 'stop') {
        await bgDaemonStop()
      } else if (
        sub === 'install' ||
        sub === 'uninstall' ||
        sub === 'enable' ||
        sub === 'disable' ||
        sub === 'restart' ||
        sub === 'is-stale' ||
        sub === 'is-active'
      ) {
        await daemonLaunchAgentVerb(sub)
      } else {
        console.error(`Unknown daemon bg subcommand: ${sub}`)
        process.exitCode = 1
      }
      break
    }
    case 'status':
      // Delegate to the bg-daemon RPC ping. Top-level `status` is a
      // shorthand for `daemon bg status`; the supervisor in this file
      // (runSupervisor) is a separate process model with no RPC of its
      // own, so showing the bg daemon's status is the most useful
      // signal here. Pass --json through.
      await bgDaemonStatus(args.includes('--json'))
      break
    case 'stop':
      // Same delegation rationale as `status`. The bg daemon owns the
      // shutdown op; the legacy supervisor in this file responds to
      // SIGTERM directly and is not addressable via shutdown RPC.
      await bgDaemonStop()
      break
    case '--help':
    case '-h':
      printHelp()
      break
    default:
      console.error(`Unknown daemon subcommand: ${subcommand}`)
      printHelp()
      process.exitCode = 1
  }
}

async function bgDaemonTailLog(): Promise<void> {
  const { join } = await import('node:path')
  const { existsSync } = await import('node:fs')
  const today = new Date().toISOString().slice(0, 10)
  const logPath = join(getConfigHomeDir(), 'telemetry', `events-${today}.jsonl`)
  if (!existsSync(logPath)) {
    console.error(`bg daemon log: no events file at ${logPath}`)
    console.error(`(set THYROX_CODE_LOCAL_TELEMETRY=1 + restart daemon to populate)`)
    process.exitCode = 1
    return
  }
  const { spawn } = await import('node:child_process')
  const tail = spawn('tail', ['-f', logPath], { stdio: 'inherit' })
  await new Promise<void>(resolve => {
    tail.on('exit', code => {
      if (code !== null && code !== 0) process.exitCode = code
      resolve()
    })
    tail.on('error', e => {
      console.error(`tail failed: ${(e as Error).message}`)
      process.exit(1)
    })
  })
}

async function bgDaemonStatus(asJson = false): Promise<void> {
  const { daemonRequest } = await import('./daemonClient.js')
  const r = await daemonRequest('ping', {}, { timeoutMs: 1000 })
  if (!r.ok) {
    if (asJson) {
      console.log(JSON.stringify({ ok: false, running: false, code: r.code }))
    } else {
      console.log(`bg daemon: not running (${r.code})`)
    }
    process.exitCode = 1
    return
  }
  const uptime = (r as Record<string, unknown>).uptime
  const list = await daemonRequest('list', {}, { timeoutMs: 2000 })
  const jobs = list.ok
    ? ((list as Record<string, unknown>).jobs as Array<Record<string, unknown>> | undefined) ?? []
    : []
  if (asJson) {
    console.log(JSON.stringify({ ok: true, running: true, uptime, jobs }, null, 2))
    return
  }
  console.log(`bg daemon: running (uptime ${uptime ?? 'unknown'}ms)`)
  if (jobs.length === 0) {
    console.log('  (no workers)')
    return
  }
  for (const j of jobs) {
    const cls = j.classifierState ? ` [${j.classifierState}/${j.classifierTempo}]` : ''
    const needs = j.classifierNeeds ? ` needs="${String(j.classifierNeeds).slice(0, 60)}"` : ''
    console.log(`  ${j.short}  ${j.status}${cls}  pid=${j.pid}  attachers=${j.attachers}${needs}`)
  }
}

async function daemonLaunchAgentVerb(
  verb: 'install' | 'uninstall' | 'enable' | 'disable' | 'restart' | 'is-stale' | 'is-active',
): Promise<void> {
  const { join } = await import('node:path')
  const la = await import('./launchAgent.js')
  const ccbDir = join(getConfigHomeDir(), 'daemon')
  const opts = {
    jsonPath: join(ccbDir, 'state.json'),
    logPath: join(ccbDir, 'daemon.log'),
  }
  if (verb === 'is-stale') {
    const stale = await la.isLaunchAgentStale()
    console.log(stale ? 'stale' : 'fresh')
    process.exitCode = stale ? 1 : 0
    return
  }
  if (verb === 'is-active') {
    const active = await la.isLaunchAgentRunning()
    console.log(active ? 'active' : 'inactive')
    process.exitCode = active ? 0 : 1
    return
  }
  let r: { ok: boolean; error?: string; servicePath?: string }
  if (verb === 'install') r = await la.installLaunchAgent(opts)
  else if (verb === 'uninstall') r = await la.uninstallLaunchAgent()
  else if (verb === 'enable') r = await la.startLaunchAgent()
  else if (verb === 'disable') r = await la.stopLaunchAgent()
  else r = await la.restartLaunchAgent()
  if (!r.ok) {
    console.error(`bg daemon ${verb}: ${r.error}`)
    process.exitCode = 1
    return
  }
  console.log(`bg daemon ${verb}: ok${r.servicePath ? ` (${r.servicePath})` : ''}`)
}

async function bgDaemonStop(): Promise<void> {
  const { daemonRequest } = await import('./daemonClient.js')
  const r = await daemonRequest('shutdown', {}, { timeoutMs: 2000 })
  if (!r.ok) {
    console.log(`bg daemon: not running (${r.code})`)
    process.exitCode = 1
    return
  }
  console.log('bg daemon: shutdown signal accepted')
}

